local ShuttleMaker = {}
local PRODUCTS = {
    iron_shuttle = { name = "Železni čolniček za tkanje", ironCost = 1, woodCost = 4, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni čolniček za prečenje niti pri tkanju." },
    bronze_shuttle = { name = "Bronast čolniček za tkanje", bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast čolniček za hitro tkanje." },
    silver_shuttle = { name = "Srebrni čolniček za tkanje", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrni čolniček za plemiške tkače." },
    gilded_shuttle = { name = "Pozlačeni čolniček za tkanje", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačeni čolniček za dvorne tkače." },
    jewel_set_shuttle = { name = "Draguljasti čolniček za tkanje", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljasti čolniček za kraljevske tkače." },
    royal_sovereign_shuttle = { name = "Kraljevski suvereni čolniček za tkanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 5, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suvereni čolniček z biseri za krono." },
}
local BUILDINGS = {
    shuttle_workshop = { name = "Čolnična delavnica", cost = { gold = 315, wood = 190, stone = 125, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    shuttle_house = { name = "Čolnična hiša", cost = { gold = 1165, wood = 375, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_shuttle_atelier = { name = "Mojstrski čolnični atelje", cost = { gold = 2935, wood = 435, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_shuttle_palace = { name = "Suverena čolnična palača", cost = { gold = 12780, wood = 655, stone = 820, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
ShuttleMaker.ironStock = 10; ShuttleMaker.bronzeStock = 8; ShuttleMaker.woodStock = 18; ShuttleMaker.leatherStock = 10; ShuttleMaker.silverStock = 8; ShuttleMaker.goldStock = 6; ShuttleMaker.jewelStock = 4; ShuttleMaker.pearlStock = 4
ShuttleMaker.productStock = {}; ShuttleMaker.buildings = {}; ShuttleMaker.maker = nil; ShuttleMaker.activeMaking = {}; ShuttleMaker.totalProducts = 0; ShuttleMaker.dayTimer = 0
function ShuttleMaker.init() ShuttleMaker.ironStock=10; ShuttleMaker.bronzeStock=8; ShuttleMaker.woodStock=18; ShuttleMaker.leatherStock=10; ShuttleMaker.silverStock=8; ShuttleMaker.goldStock=6; ShuttleMaker.jewelStock=4; ShuttleMaker.pearlStock=4; ShuttleMaker.productStock={}; ShuttleMaker.buildings={}; ShuttleMaker.maker=nil; ShuttleMaker.activeMaking={}; ShuttleMaker.totalProducts=0; ShuttleMaker.dayTimer=0; print("[ShuttleMaker] Royal Shuttle Maker System initialized (6 products, 4 buildings)") end
function ShuttleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ShuttleMaker.maker={name=n or ("Čolničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čolničar najet: %s (spretnost: %d)",ShuttleMaker.maker.name,s),"success") end; return true end
function ShuttleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ShuttleMaker.build(id) local ok,e=ShuttleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ShuttleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ShuttleMaker.getQualityBonus() local b=0; for _,bd in ipairs(ShuttleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ShuttleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ShuttleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ShuttleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ShuttleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ShuttleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ShuttleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ShuttleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ShuttleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ShuttleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ShuttleMaker.buildings==0 then return false,"Potrebna čolnična delavnica" end; if not ShuttleMaker.maker then return false,"Potreben čolničar" end; return true end
function ShuttleMaker.make(pt,qty) qty=qty or 1; local ok,e=ShuttleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ShuttleMaker.ironStock=ShuttleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ShuttleMaker.bronzeStock=ShuttleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ShuttleMaker.woodStock=ShuttleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ShuttleMaker.leatherStock=ShuttleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ShuttleMaker.silverStock=ShuttleMaker.silverStock-d.silverCost*qty end; if d.goldCost then ShuttleMaker.goldStock=ShuttleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ShuttleMaker.jewelStock=ShuttleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ShuttleMaker.pearlStock=ShuttleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ShuttleMaker.maker then t=math.max(1,t-math.floor(ShuttleMaker.maker.skill/13)) end; table.insert(ShuttleMaker.activeMaking,{id="shuttle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ShuttleMaker.completeMaking(m) local q=1.0+(ShuttleMaker.getQualityBonus()/100); if ShuttleMaker.maker then q=q+(ShuttleMaker.maker.skill/140) end; q=math.min(2.5,q); ShuttleMaker.productStock[m.productType]=(ShuttleMaker.productStock[m.productType] or 0)+m.quantity; ShuttleMaker.totalProducts=ShuttleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ShuttleMaker.maker then ShuttleMaker.maker.itemsMade=ShuttleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ShuttleMaker.maker.skill=math.min(100,ShuttleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čolniček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shuttle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ShuttleMaker.update(dt) if not _G.state then return end; ShuttleMaker.dayTimer=ShuttleMaker.dayTimer+dt; if ShuttleMaker.dayTimer>=30 then ShuttleMaker.dayTimer=0; for i=#ShuttleMaker.activeMaking,1,-1 do local m=ShuttleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ShuttleMaker.completeMaking(m); table.remove(ShuttleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ShuttleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ShuttleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ShuttleMaker.getStats() return {ironStock=ShuttleMaker.ironStock,bronzeStock=ShuttleMaker.bronzeStock,woodStock=ShuttleMaker.woodStock,leatherStock=ShuttleMaker.leatherStock,silverStock=ShuttleMaker.silverStock,goldStock=ShuttleMaker.goldStock,jewelStock=ShuttleMaker.jewelStock,pearlStock=ShuttleMaker.pearlStock,productStock=ShuttleMaker.productStock,numBuildings=#ShuttleMaker.buildings,hasMaker=ShuttleMaker.maker~=nil,makerName=ShuttleMaker.maker and ShuttleMaker.maker.name or "—",makerSkill=ShuttleMaker.maker and ShuttleMaker.maker.skill or 0,activeMaking=#ShuttleMaker.activeMaking,totalProducts=ShuttleMaker.totalProducts} end
return ShuttleMaker
